#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <pthread.h>

#define HT_SIZE 4096
#define HT_MASK (HT_SIZE - 1)
#define MAX_THREADS 8

typedef struct {
    char *key;
    uint32_t len;
    uint32_t hash;
    double sum;
    int64_t sum_cents; // exact cents accumulation for 2-decimal inputs
} Entry;

typedef struct {
    Entry entries[HT_SIZE];
    int used_indices[HT_SIZE];
    int num_used;
    int all_two_dec;
} HashTable;

static inline uint32_t hash_bytes(const char *p, uint32_t len) {
    uint32_t h = 2166136261u;
    for (uint32_t i = 0; i < len; i++) {
        h ^= (uint8_t)p[i];
        h *= 16777619u;
    }
    return h ? h : 1;
}

static inline void ht_init(HashTable *ht) {
    memset(ht->entries, 0, sizeof(ht->entries));
    ht->num_used = 0;
    ht->all_two_dec = 1;
}

static inline Entry* ht_find_or_insert(HashTable *ht, const char *key, uint32_t len, uint32_t h, int copy_key) {
    uint32_t idx = h & HT_MASK;
    while (1) {
        Entry *e = &ht->entries[idx];
        if (e->hash == 0) {
            e->hash = h;
            e->len = len;
            if (copy_key) {
                char *k = (char *)malloc(len + 1);
                memcpy(k, key, len);
                k[len] = '\0';
                e->key = k;
            } else {
                e->key = (char *)key;
            }
            e->sum = 0.0;
            e->sum_cents = 0;
            ht->used_indices[ht->num_used++] = idx;
            return e;
        }
        if (e->hash == h && e->len == len && memcmp(e->key, key, len) == 0) {
            return e;
        }
        idx = (idx + 1) & HT_MASK;
    }
}

typedef struct {
    const char *start;
    const char *end;
    HashTable ht;
} ThreadArg;

static void* process_chunk(void *arg) {
    ThreadArg *targ = (ThreadArg *)arg;
    const char *p = targ->start;
    const char *end = targ->end;
    HashTable *ht = &targ->ht;
    ht_init(ht);

    while (p < end) {
        // 1. skip id up to ','
        const char *comma1 = (const char *)memchr(p, ',', end - p);
        if (!comma1) break;
        const char *cat_start = comma1 + 1;
        if (cat_start >= end) break;

        // 2. scan cat and compute hash simultaneously
        const char *c = cat_start;
        uint32_t h = 2166136261u;
        while (c < end && *c != ',') {
            h ^= (uint8_t)*c;
            h *= 16777619u;
            c++;
        }
        if (c >= end) break;
        uint32_t cat_len = (uint32_t)(c - cat_start);
        if (h == 0) h = 1;

        // 3. parse val up to '\n'
        p = c + 1;
        int neg = 0;
        if (p < end && *p == '-') {
            neg = 1;
            p++;
        }
        int64_t int_part = 0;
        while (p < end && (unsigned)(*p - '0') <= 9) {
            int_part = int_part * 10 + (*p - '0');
            p++;
        }
        int64_t frac_part = 0;
        int frac_digits = 0;
        if (p < end && *p == '.') {
            p++;
            while (p < end && (unsigned)(*p - '0') <= 9) {
                frac_part = frac_part * 10 + (*p - '0');
                frac_digits++;
                p++;
            }
        }
        while (p < end && *p != '\n') p++;
        if (p < end && *p == '\n') p++;

        Entry *e = ht_find_or_insert(ht, cat_start, cat_len, h, 0);
        if (frac_digits == 2) {
            int64_t cents = int_part * 100 + frac_part;
            e->sum_cents += neg ? -cents : cents;
        } else if (frac_digits == 0) {
            int64_t cents = int_part * 100;
            e->sum_cents += neg ? -cents : cents;
        } else if (frac_digits == 1) {
            int64_t cents = int_part * 100 + frac_part * 10;
            e->sum_cents += neg ? -cents : cents;
        } else {
            ht->all_two_dec = 0;
            static const double pow10[] = {1.0, 10.0, 100.0, 1000.0, 10000.0, 100000.0, 1000000.0, 10000000.0, 100000000.0};
            double v = (double)int_part + (double)frac_part / (frac_digits <= 8 ? pow10[frac_digits] : 1e9);
            e->sum += neg ? -v : v;
        }
    }
    return NULL;
}

static int cmp_entries(const void *a, const void *b) {
    const Entry *ea = *(const Entry **)a;
    const Entry *eb = *(const Entry **)b;
    uint32_t min_len = ea->len < eb->len ? ea->len : eb->len;
    int cmp = memcmp(ea->key, eb->key, min_len);
    if (cmp != 0) return cmp;
    return (ea->len > eb->len) - (ea->len < eb->len);
}

int run_csvsum(void) {
    struct stat st;
    const char *data = NULL;
    size_t size = 0;
    int is_mmap = 0;

    if (fstat(0, &st) == 0 && S_ISREG(st.st_mode) && st.st_size > 0) {
        size = (size_t)st.st_size;
        void *m = mmap(NULL, size, PROT_READ, MAP_PRIVATE, 0, 0);
        if (m != MAP_FAILED) {
            data = (const char *)m;
            is_mmap = 1;
        }
    }

    if (!data) {
        size_t cap = 64 * 1024 * 1024;
        char *buf = (char *)malloc(cap);
        if (!buf) return 1;
        size = 0;
        while (1) {
            if (size == cap) {
                cap *= 2;
                buf = (char *)realloc(buf, cap);
                if (!buf) return 1;
            }
            ssize_t n = read(0, buf + size, cap - size);
            if (n <= 0) break;
            size += n;
        }
        data = buf;
    }

    if (size == 0) return 0;

    // Skip header line
    const char *p = (const char *)memchr(data, '\n', size);
    if (!p) return 0;
    p++;
    const char *end = data + size;

    int num_threads = (end - p > 1024 * 1024) ? MAX_THREADS : 1;
    pthread_t threads[MAX_THREADS];
    ThreadArg args[MAX_THREADS];

    size_t rem = (size_t)(end - p);
    const char *cur = p;
    int actual_threads = 0;
    for (int t = 0; t < num_threads && cur < end; t++) {
        const char *chunk_end = (t == num_threads - 1) ? end : (p + (rem * (t + 1)) / num_threads);
        if (chunk_end < end) {
            const char *nl = (const char *)memchr(chunk_end, '\n', end - chunk_end);
            chunk_end = nl ? (nl + 1) : end;
        }
        if (cur < chunk_end) {
            args[actual_threads].start = cur;
            args[actual_threads].end = chunk_end;
            actual_threads++;
            cur = chunk_end;
        }
    }

    for (int t = 1; t < actual_threads; t++) {
        pthread_create(&threads[t], NULL, process_chunk, &args[t]);
    }
    if (actual_threads > 0) {
        process_chunk(&args[0]);
    }
    for (int t = 1; t < actual_threads; t++) {
        pthread_join(threads[t], NULL);
    }

    // Merge into args[0].ht
    HashTable *master = &args[0].ht;
    for (int t = 1; t < actual_threads; t++) {
        HashTable *ht = &args[t].ht;
        if (!ht->all_two_dec) master->all_two_dec = 0;
        for (int i = 0; i < ht->num_used; i++) {
            Entry *src = &ht->entries[ht->used_indices[i]];
            Entry *dst = ht_find_or_insert(master, src->key, src->len, src->hash, 0);
            dst->sum_cents += src->sum_cents;
            dst->sum += src->sum;
        }
    }

    Entry *list[HT_SIZE];
    for (int i = 0; i < master->num_used; i++) {
        list[i] = &master->entries[master->used_indices[i]];
    }
    qsort(list, master->num_used, sizeof(Entry *), cmp_entries);

    char outbuf[65536];
    size_t outpos = 0;
    for (int i = 0; i < master->num_used; i++) {
        Entry *e = list[i];
        double total = (double)e->sum_cents / 100.0 + e->sum;
        if (outpos + e->len + 64 > sizeof(outbuf)) {
            write(1, outbuf, outpos);
            outpos = 0;
        }
        memcpy(outbuf + outpos, e->key, e->len);
        outpos += e->len;
        outbuf[outpos++] = ',';
        outpos += snprintf(outbuf + outpos, 64, "%.2f\n", total);
    }
    if (outpos > 0) {
        write(1, outbuf, outpos);
    }

    if (is_mmap) {
        munmap((void *)data, size);
    }
    return 0;
}
